Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

$Root = (Get-Location).Path
$ExpectedBranch = "feature/vitrine-marketplace"
$TargetRelative = "components\financeiro\FinancialAreaClient.tsx"
$Target = Join-Path $Root $TargetRelative
$Backup = "$Target.orcaly-financeiro-backup"
$Utf8 = New-Object System.Text.UTF8Encoding($false)

if (-not (Test-Path -LiteralPath (Join-Path $Root "package.json"))) {
  throw "Execute este script na raiz do projeto Orçaly."
}

$Branch = (& git branch --show-current | Out-String).Trim()
if ($Branch -ne $ExpectedBranch) {
  throw "Branch atual: $Branch. Use a branch $ExpectedBranch."
}

if (-not (Test-Path -LiteralPath $Target)) {
  throw "Arquivo não encontrado: $TargetRelative"
}

$Current = Get-Content -LiteralPath $Target -Raw

if ($Current -notmatch "export default function FinancialAreaClient") {
  throw "O componente financeiro não está na estrutura esperada. Nenhuma alteração foi aplicada."
}

Copy-Item -LiteralPath $Target -Destination $Backup -Force

try {
  Write-Host "==> Aplicando visual organizado do Financeiro" -ForegroundColor Cyan

  $Base64 = @'

'@

  $Bytes = [Convert]::FromBase64String(($Base64 -replace "\s", ""))
  $Content = [Text.Encoding]::UTF8.GetString($Bytes)

  [IO.File]::WriteAllText(
    $Target,
    $Content.TrimEnd() + "`n",
    $Utf8
  )

  $Checks = @(
    "ORCALY_FINANCEIRO_ORGANIZADO_V3",
    "Fluxo do mês",
    "Visão geral",
    "Entradas e saídas",
    "Contas a receber",
    "Contas a pagar",
    "Materiais e custos",
    "Notas fiscais",
    "purpose: 'finance-document'",
    "resolvePanelStorageUrl",
    ".eq('company_id', company.id)"
  )

  foreach ($Check in $Checks) {
    $Match = Select-String `
      -LiteralPath $Target `
      -Pattern $Check `
      -SimpleMatch `
      -ErrorAction SilentlyContinue

    if (-not $Match) {
      throw "Verificação falhou: $Check"
    }

    Write-Host "[OK] $Check" -ForegroundColor Green
  }

  Write-Host ""
  Write-Host "==> Verificando diff" -ForegroundColor Cyan
  & git diff --check -- $TargetRelative

  if ($LASTEXITCODE -ne 0) {
    throw "git diff --check encontrou problemas."
  }

  if (Test-Path -LiteralPath (Join-Path $Root ".next")) {
    Remove-Item -LiteralPath (Join-Path $Root ".next") -Recurse -Force
  }

  Write-Host ""
  Write-Host "==> Executando build completo" -ForegroundColor Cyan
  & npm run build
  $BuildExitCode = $LASTEXITCODE

  Write-Host ""
  Write-Host "BUILD_EXIT_CODE=$BuildExitCode" -ForegroundColor Yellow

  if ($BuildExitCode -ne 0) {
    throw "O build falhou."
  }

  Remove-Item -LiteralPath $Backup -Force

  Write-Host ""
  Write-Host "==================================================" -ForegroundColor Magenta
  Write-Host "FINANCEIRO ORGANIZADO E APROVADO" -ForegroundColor Magenta
  Write-Host "==================================================" -ForegroundColor Magenta
  Write-Host "Componente: components/financeiro/FinancialAreaClient.tsx"
  Write-Host "Áreas preservadas: visão geral, lançamentos, receber, pagar, materiais e notas"
  Write-Host "Funções preservadas: filtros, cadastro, status, anexos privados e links temporários"
  Write-Host "Visual: resumo mensal, fluxo, navegação compacta, tabela responsiva e formulário organizado"
  Write-Host ""
  Write-Host "Nenhum commit, push ou deploy foi criado."
}
catch {
  Write-Host ""
  Write-Host "Falha detectada. Restaurando o Financeiro anterior..." -ForegroundColor Red

  if (Test-Path -LiteralPath $Backup) {
    Copy-Item -LiteralPath $Backup -Destination $Target -Force
    Remove-Item -LiteralPath $Backup -Force
  }

  throw
}
